// msg.payload is the raw file text, read by the preceding "file in" core
// node — no require('fs'). Function nodes are sandboxed and don't expose
// Node's require() by default; this was the actual bug (not a version
// issue — plain require() has never worked in a stock Function node).
let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
msg.job_name = 'oura_sync';
msg.influx_start_point = 'sync_job_runs,job_name=oura_sync,status=started value=1 ' + (Date.now() * 1000000);
return msg;

// GoDaddy is now the source of truth for oura_client_id/oura_client_secret
// (PLAN.md §3, decided — no longer hand-copied into wardstock_secrets.json).
// Fetched fresh every run rather than only when a token refresh is
// actually needed, to keep this simple — one extra cheap call, no
// branching on whether the fetch is 'needed' this run.
msg.url = msg.secrets.godaddy_base_url + '/api/get_shared_config.php';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token };
return msg;

// If this fetch fails for any reason (GoDaddy unreachable, auth issue),
// fall back to whatever's still in the local secrets file rather than
// hard-failing the whole flow — the local .example no longer expects
// these fields to be filled in, but an install that still has stale
// local values (from before this change) keeps working as a fallback.
const resp = msg.payload;
if (resp && resp.oura_client_id && resp.oura_client_secret) {
    msg.secrets.oura_client_id = resp.oura_client_id;
    msg.secrets.oura_client_secret = resp.oura_client_secret;
} else {
    node.warn('get_shared_config.php did not return usable values — falling back to local secrets file (if any). Response: ' + JSON.stringify(resp));
}
return msg;

// FIX (Aug 2026, real bug hit on first live test run): this node was
// missing entirely. The intervening GoDaddy get_shared_config.php call
// (two nodes upstream) overwrites msg.url/msg.headers with its own GET
// request details on the way through, so by the time execution reaches
// the InfluxDB write those need rebuilding from msg.secrets -- same
// pattern already used correctly for the batch and finish-point writes
// further downstream in this flow. msg.influx_start_point itself was
// already built back in "Load secrets + start job log"; this just wraps
// it into an actual HTTP request.
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_start_point;
return msg;

// Mirrors oura_ensure_valid_token() in oura.php: refresh if expiring
// within 60 seconds, otherwise reuse the stored token untouched.
//
// FIX (Aug 2026, real bug hit on first live test run): new Date(x).getTime()
// returns NaN for anything unparseable (e.g. oura_expires_at still holding
// its literal .example placeholder text, pre-first-auth) -- and any
// comparison against NaN is always false in JS. That silently made
// needsRefresh evaluate to false instead of true, so a placeholder/missing
// expires_at was treated as "token still valid" and the flow limped ahead
// with whatever stale oura_access_token happened to be in the secrets file,
// rather than refreshing (or clearly failing) up front. Guard explicitly:
// unparseable always counts as needing refresh.
const secrets = msg.secrets;
const expiresAt = new Date(secrets.oura_expires_at || 0).getTime();
const needsRefresh = !Number.isFinite(expiresAt) || (expiresAt <= Date.now() + 60000);
msg.needs_refresh = needsRefresh;
if (needsRefresh) {
    msg.url = 'https://api.ouraring.com/oauth/token';
    msg.method = 'POST';
    msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
    const params = new URLSearchParams({
        grant_type: 'refresh_token',
        refresh_token: secrets.oura_refresh_token,
        client_id: secrets.oura_client_id,
        client_secret: secrets.oura_client_secret
    });
    msg.payload = params.toString();
}
return msg;

// Prepares the write instead of doing it directly — the actual write
// happens in the following "file" (write) core node, not via
// require('fs') here. Oura ROTATES the refresh token on every use, so
// the NEW refresh_token must be saved every time; reusing the old one
// fails on the next run.
if (!msg.payload || !msg.payload.access_token) {
    msg.job_failed = true;
    msg.failure_code = 'oura_auth_failed';
    msg.failure_detail = 'token refresh did not return access_token: ' + JSON.stringify(msg.payload);
    return [null, msg];
}
const secrets = msg.secrets;
secrets.oura_access_token = msg.payload.access_token;
secrets.oura_refresh_token = msg.payload.refresh_token;
secrets.oura_expires_at = new Date(Date.now() + (msg.payload.expires_in * 1000)).toISOString();
msg.secrets = secrets;
msg.filename = '/share/wardstock_secrets.json';
msg.payload = JSON.stringify(secrets, null, 2);
return [msg, null];

// Mirrors oura_fetch_day()'s window logic in oura.php EXACTLY — this is
// the part that took real debugging to get right on the PHP side (a
// same-day query misses sessions starting the evening before; even a
// 2-day window missed one due to an apparent exclusive end_date
// boundary interacting with UTC). Use date-1 to date+1 as the FLOOR
// behavior, always. Do not simplify this without re-reading PLAN.md and
// the PHP oura.php comments explaining why.
//
// SELF-HEAL FIX (PLAN.md §1 TODO, Aug 2026): the original version of this
// function only ever used 'yesterday' as the window start, so a missed
// run (or a day Oura genuinely had no data for yet) never got caught up
// later — confirmed live: today's reading synced fine, yesterday's
// stayed missing. Fixed by reading the last-confirmed-data-date helper
// (n_oura_read_last_data_date, upstream) and using whichever is EARLIER
// of that and 'yesterday' as the actual start — normal runs behave
// identically to before (helper stays one day behind, same as 'yesterday'
// would be), but a stale helper (missed runs, gap) extends the window
// back automatically to close the gap, rather than silently skipping it.
const today = new Date();
const target = today.toISOString().slice(0, 10); // today
const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);

let start = yesterday;
// from n_oura_read_last_data_date; unset on first run (new helper, no
// default). HA's state string for a datetime helper is typically
// 'YYYY-MM-DD HH:MM:SS' (space, not 'T') — new Date() parses that
// leniently in Node.js in practice, but isn't spec-guaranteed; the
// isNaN check below is the actual safety net if a palette-version
// quirk ever returns something unparseable, not just belt-and-suspenders.
const lastDataDateStr = msg.oura_last_data_date;
if (lastDataDateStr) {
    const lastDataDate = new Date(lastDataDateStr);
    if (!isNaN(lastDataDate.getTime()) && lastDataDate < yesterday) {
        start = lastDataDate;
    }
}
const end = new Date(today); end.setDate(end.getDate() + 1);
const startStr = start.toISOString().slice(0, 10);
const endStr = end.toISOString().slice(0, 10);

msg.target_date = target;
msg.oura_query = { start_date: startStr, end_date: endStr };
msg.access_token = msg.secrets.oura_access_token;

msg.url = 'https://api.ouraring.com/v2/usercollection/sleep?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.sleep_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_activity?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.activity_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_readiness?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

// PULL EVERYTHING AVAILABLE (Ward, Aug 2026) — the original 3 endpoints
// (sleep/daily_activity/daily_readiness) missed most of what Oura tracks.
// heartrate is the concrete original ask: continuous all-day heart rate,
// not just the sleep-embedded 5-min series — see PLAN.md §1's "Known gap"
// note for the full explanation. This endpoint is DIFFERENT from every
// other Oura call in this flow: it takes start_datetime/end_datetime
// (full ISO datetimes), not start_date/end_date — continuous data needs
// time bounds, not just day bounds. Scope 'heartrate' was already being
// requested by oura_connect.php even before this change, so this specific
// endpoint may work without Ward needing to reconnect — unlike the ones
// chained after it.
msg.readiness_response = msg.payload;
const startDt = msg.oura_query.start_date + 'T00:00:00';
const endDt = msg.oura_query.end_date + 'T23:59:59';
msg.url = 'https://api.ouraring.com/v2/usercollection/heartrate?' +
    new URLSearchParams({ start_datetime: startDt, end_datetime: endDt }).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

// Endpoints below are moderate-confidence, not verified against a real
// Oura account (see PLAN.md §1's "Known gap" note) — same start_date/
// end_date shape as the original 3 endpoints, unlike heartrate above.
msg.heartrate_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_spo2?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.spo2_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_stress?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.stress_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_resilience?' +
