msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.workout_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/session?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

// enhanced_tag: lowest confidence of the new endpoints — Oura has
// renamed/changed tag-endpoint shape across API versions, this name/
// query-shape is the current best guess from documentation, not confirmed.
msg.session_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/enhanced_tag?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

// daily_sleep is a distinct SCORE/summary endpoint, separate from
// /sleep (the full per-session data with embedded heart_rate/hrv/phase
// this flow already pulls) — confirmed as its own real endpoint via web
// search (Aug 2026), not previously in this flow at all.
msg.tag_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_sleep?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.daily_sleep_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/daily_cardiovascular_age?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

msg.cardio_age_response = msg.payload;
msg.url = 'https://api.ouraring.com/v2/usercollection/vO2_max?' +
    new URLSearchParams(msg.oura_query).toString();
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + msg.access_token };
return msg;

// LOG ALL THE DATA (Ward's instruction, not just the WardStock summary
// subset) — captures every scalar field from each record, PLUS
// decomposes the 5-minute heart_rate/hrv arrays into individual
// timestamped InfluxDB points (the actual high-fidelity data WardStock
// itself never captured). Dense per-30-second phase/movement bitstrings
// were originally stored as a single raw string field per record and
// left undecomposed — sleep_phase_30_sec now ALSO gets decomposed into
// real per-15-min oura_sleep_stage points (see decomposeSleepPhase()
// below, PLAN.md §11 #20). movement_30_sec remains raw-string-only for
// now — no analysis in §11 currently needs it decomposed, revisit if
// one ever does.
msg.vo2max_response = msg.payload;
const lines = [];
const nowNs = Date.now() * 1000000;

function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }

function sleepRecordToLine(r) {
    const tags = ['oura_sleep', 'type=' + esc(r.type || 'unknown'), 'day=' + esc(r.day)].join(',');
    const scalarFields = ['average_breath','average_heart_rate','average_hrv','awake_time',
        'deep_sleep_duration','efficiency','latency','light_sleep_duration','lowest_heart_rate',
        'period','rem_sleep_duration','restless_periods','time_in_bed','total_sleep_duration',
        'readiness_score_delta','sleep_score_delta'];
    const parts = [];
    scalarFields.forEach(f => { if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]); });
    parts.push('id="' + (r.id || '') + '"');
    parts.push('sleep_phase_30_sec="' + (r.sleep_phase_30_sec || '') + '"');
    parts.push('movement_30_sec="' + (r.movement_30_sec || '') + '"');
    // Real Oura field for "when did I actually get out of bed," captured
    // starting Aug 2026 -- previously only bedtime_start was written,
    // leaving #19's bedtime/wake-time trend to approximate wake time as
    // bedtime + time_in_bed, which turned out to run 9-14 HOURS on real
    // data (Ward's own real nights are ~5-6 hours) -- time_in_bed
    // evidently includes time lying awake in bed after actually waking,
    // not just time asleep. Only written when Oura's own response
    // includes it, matching the null/undefined guard every scalarFields
    // entry above already gets.
    if (r.bedtime_end) parts.push('bedtime_end="' + r.bedtime_end + '"');
    // Embedded per-session readiness sub-object (distinct from the
    // separate /daily_readiness endpoint — both exist, keep them
    // distinguishable, see PLAN.md note on this).
    if (r.readiness) {
        parts.push('embedded_readiness_score=' + r.readiness.score);
        if (r.readiness.contributors) {
            Object.entries(r.readiness.contributors).forEach(([k, v]) => {
                if (v !== null) parts.push('embedded_readiness_' + k + '=' + v);
            });
        }
        if (r.readiness.temperature_deviation !== null) parts.push('temperature_deviation=' + r.readiness.temperature_deviation);
        if (r.readiness.temperature_trend_deviation !== null) parts.push('temperature_trend_deviation=' + r.readiness.temperature_trend_deviation);
    }
    const ts = r.bedtime_start ? new Date(r.bedtime_start).getTime() * 1000000 : nowNs;
    return tags + ' ' + parts.join(',') + ' ' + ts;
}

function decomposeTimeSeries(measurement, r, key) {
    if (!r[key] || !r[key].items || !r.bedtime_start) return [];
    const interval = r[key].interval || 300;
    const base = new Date(r.bedtime_start).getTime();
    const out = [];
    r[key].items.forEach((val, i) => {
        if (val === null || val === undefined) return;
        const ts = (base + i * interval * 1000) * 1000000;
        out.push(measurement + ',sleep_id=' + esc(r.id) + ' value=' + val + ' ' + ts);
    });
    return out;
}

// SLEEP-STAGE HYPNOGRAM DECOMPOSITION (PLAN.md §11 #20, Aug 2026) — the
// follow-up this function's own original comment flagged as "a
// reasonable follow-up enhancement, not done in this first pass": turns
// the raw sleep_phase_30_sec string (one digit per 30-second epoch,
// stored as-is above) into real per-15-minute-bucket InfluxDB points,
// same as decomposeTimeSeries() does for heart_rate/hrv, so the hypnogram
// chart has something to actually query.
//
// STAGE_MAP IS ASSUMED, NOT CONFIRMED — this is the digit convention
// documented for Oura's 5-minute hypnogram field elsewhere in their API
// (1=deep, 2=light, 3=REM, 4=awake), carried over on the assumption
// sleep_phase_30_sec uses the same digit meanings at finer granularity.
// This has NOT been checked against a real synced sleep_phase_30_sec
// string from Ward's own data. Same "verify against real behavior"
// requirement as everywhere else uncertain in this project (e.g. §10's
// Oura-400-vs-401 finding) — on first real run, spot-check a few
// decoded stages against what Ward actually remembers about that
// night's sleep, and fix STAGE_MAP below if the digits mean something
// else. Nothing else in this function needs to change if so.
const SLEEP_STAGE_MAP = { '1': 'deep', '2': 'light', '3': 'rem', '4': 'awake' };
function decomposeSleepPhase(r) {
    if (!r.sleep_phase_30_sec || !r.bedtime_start) return [];
    const EPOCH_SECONDS = 30;
    const BUCKET_SECONDS = 900; // 15 minutes, per PLAN.md §11 #20's requested resolution
    const epochsPerBucket = BUCKET_SECONDS / EPOCH_SECONDS;
    const base = new Date(r.bedtime_start).getTime();
    const chars = String(r.sleep_phase_30_sec).split('');
    const out = [];
    // Majority vote per 15-minute bucket (most common stage in that
    // window), not a stride-sample of every 30th epoch — so a brief
    // awakening inside an otherwise-asleep window doesn't just vanish.
    for (let i = 0; i < chars.length; i += epochsPerBucket) {
        const bucketChars = chars.slice(i, i + epochsPerBucket);
        const counts = {};
        bucketChars.forEach(c => {
            const stage = SLEEP_STAGE_MAP[c] || 'unknown';
            counts[stage] = (counts[stage] || 0) + 1;
        });
        const majorityStage = Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0];
        const ts = (base + i * EPOCH_SECONDS * 1000) * 1000000;
        out.push('oura_sleep_stage,sleep_id=' + esc(r.id) + ',stage=' + esc(majorityStage) + ' value=1 ' + ts);
    }
    return out;
}

const sleepRecords = (msg.sleep_response && msg.sleep_response.data) || [];
sleepRecords.forEach(r => {
    lines.push(sleepRecordToLine(r));
    lines.push(...decomposeTimeSeries('oura_heart_rate', r, 'heart_rate'));
    lines.push(...decomposeTimeSeries('oura_hrv', r, 'hrv'));
    lines.push(...decomposeSleepPhase(r));
});

const activityRecords = (msg.activity_response && msg.activity_response.data) || [];
activityRecords.forEach(r => {
    const parts = [];
    Object.entries(r).forEach(([k, v]) => {
        if (typeof v === 'number') parts.push(k + '=' + v);
        else if (typeof v === 'string' && k !== 'day' && k !== 'class_5_min') parts.push(k + '="' + v.replace(/"/g,'') + '"');
    });
    if (parts.length) lines.push('oura_daily_activity,day=' + esc(r.day) + ' ' + parts.join(',') + ' ' + nowNs);
});

const readinessRecords = (msg.readiness_response && msg.readiness_response.data) || [];
readinessRecords.forEach(r => {
    const parts = ['score=' + r.score];
    if (r.contributors) {
        Object.entries(r.contributors).forEach(([k, v]) => { if (v !== null) parts.push(k + '=' + v); });
    }
    if (parts.length) lines.push('oura_daily_readiness,day=' + esc(r.day) + ' ' + parts.join(',') + ' ' + nowNs);
});

// PULL EVERYTHING AVAILABLE (Ward, Aug 2026, PLAN.md §1 "Known gap") —
// the 10 blocks below are new. Field names for the moderate-confidence
// endpoints (spo2/stress/resilience/workout/session/tag/daily_sleep/
// cardio_age/vo2max) are reasoned from Oura's documented API, not
// confirmed against a real response — same discipline as everywhere else
// uncertain in this project. Check Node-RED's debug output after first
// real run for which of these actually match; a wrong field name just
// means that measurement's points come out with fewer/no fields, not a
// crash, thanks to the defensive (x && x.data) || [] pattern throughout.

// heartrate: HIGH confidence — continuous all-day feed, the original ask.
// Kept in its own measurement (oura_heartrate_all_day), deliberately NOT
// merged with the sleep-embedded oura_heart_rate series (different
// source/sampling characteristics — conflating them would make "was this
// a sleep sample or an all-day sample" ambiguous for later Flux queries).
const heartrateRecords = (msg.heartrate_response && msg.heartrate_response.data) || [];
heartrateRecords.forEach(r => {
    if (r.bpm === null || r.bpm === undefined || !r.timestamp) return;
    const ts = new Date(r.timestamp).getTime() * 1000000;
    if (!Number.isFinite(ts)) return;
    lines.push('oura_heartrate_all_day,source=' + esc(r.source || 'unknown') + ' bpm=' + r.bpm + ' ' + ts);
});

const spo2Records = (msg.spo2_response && msg.spo2_response.data) || [];
spo2Records.forEach(r => {
    const parts = [];
    if (r.spo2_percentage && r.spo2_percentage.average !== null && r.spo2_percentage.average !== undefined) parts.push('average=' + r.spo2_percentage.average);
    if (r.breathing_disturbance_index !== null && r.breathing_disturbance_index !== undefined) parts.push('breathing_disturbance_index=' + r.breathing_disturbance_index);
    if (parts.length) lines.push('oura_daily_spo2,day=' + esc(r.day) + ' ' + parts.join(',') + ' ' + nowNs);
});

// daily_stress: worth calling out — arguably the single most directly
// relevant new data point this project could add, given wherewhen's
// whole purpose is detecting elevated stress/anxiety (see PLAN.md §1).
const stressRecords = (msg.stress_response && msg.stress_response.data) || [];
stressRecords.forEach(r => {
    const parts = [];
    ['stress_high','recovery_high'].forEach(f => { if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]); });
    if (r.day_summary) parts.push('day_summary="' + esc(r.day_summary) + '"');
    if (parts.length) lines.push('oura_daily_stress,day=' + esc(r.day) + ' ' + parts.join(',') + ' ' + nowNs);
});

const resilienceRecords = (msg.resilience_response && msg.resilience_response.data) || [];
resilienceRecords.forEach(r => {
    const parts = [];
    if (r.level) parts.push('level="' + esc(r.level) + '"');
    if (r.contributors) {
        Object.entries(r.contributors).forEach(([k, v]) => { if (v !== null && v !== undefined) parts.push(k + '=' + v); });
    }
    if (parts.length) lines.push('oura_daily_resilience,day=' + esc(r.day) + ' ' + parts.join(',') + ' ' + nowNs);
});

const workoutRecords = (msg.workout_response && msg.workout_response.data) || [];
workoutRecords.forEach(r => {
    const ts = r.start_datetime ? new Date(r.start_datetime).getTime() * 1000000 : nowNs;
    const parts = [];
    ['calories','distance'].forEach(f => { if (r[f] !== null && r[f] !== undefined) parts.push(f + '=' + r[f]); });
    parts.push('id="' + (r.id || '') + '"');
    parts.push('end_datetime="' + (r.end_datetime || '') + '"');
    lines.push('oura_workout,activity=' + esc(r.activity || 'unknown') + ',intensity=' + esc(r.intensity || 'unknown') + ',source=' + esc(r.source || 'unknown') + ' ' + parts.join(',') + ' ' + ts);
});

// session: Oura's own guided sessions (breathing/meditation/rest) —
// worth watching for overlap with Ward's self-directed therapy work
// (PLAN.md §19's therapy_history_reference self_therapy entry).
const sessionRecords = (msg.session_response && msg.session_response.data) || [];
sessionRecords.forEach(r => {
    const ts = r.start_datetime ? new Date(r.start_datetime).getTime() * 1000000 : nowNs;
    const parts = [];
    parts.push('id="' + (r.id || '') + '"');
    parts.push('end_datetime="' + (r.end_datetime || '') + '"');
    if (r.mood) parts.push('mood="' + esc(r.mood) + '"');
    lines.push('oura_session,type=' + esc(r.type || 'unknown') + ' ' + parts.join(',') + ' ' + ts);
});

// enhanced_tag: LOWEST confidence of the new endpoints — Oura has
// changed tag-endpoint naming/shape across API versions.
const tagRecords = (msg.tag_response && msg.tag_response.data) || [];
tagRecords.forEach(r => {
    const ts = r.start_time ? new Date(r.start_time).getTime() * 1000000 : nowNs;
    const parts = [];
    parts.push('id="' + (r.id || '') + '"');
    if (r.comment) parts.push('comment="' + esc(r.comment) + '"');
    if (r.end_time) parts.push('end_time="' + r.end_time + '"');
    lines.push('oura_tag,tag_type=' + esc(r.tag_type_code || 'unknown') + ' ' + parts.join(',') + ' ' + ts);
});

// daily_sleep: the SCORE/summary endpoint, distinct from /sleep's full
// per-session data (already captured above via sleepRecordToLine).
const dailySleepRecords = (msg.daily_sleep_response && msg.daily_sleep_response.data) || [];
dailySleepRecords.forEach(r => {
    const parts = [];
    if (r.score !== null && r.score !== undefined) parts.push('score=' + r.score);
    if (r.contributors) {
        Object.entries(r.contributors).forEach(([k, v]) => { if (v !== null && v !== undefined) parts.push(k + '=' + v); });
    }
    if (parts.length) lines.push('oura_daily_sleep_score,day=' + esc(r.day) + ' ' + parts.join(',') + ' ' + nowNs);
});

const cardioAgeRecords = (msg.cardio_age_response && msg.cardio_age_response.data) || [];
cardioAgeRecords.forEach(r => {
    if (r.vascular_age === null || r.vascular_age === undefined) return;
    lines.push('oura_daily_cardiovascular_age,day=' + esc(r.day) + ' vascular_age=' + r.vascular_age + ' ' + nowNs);
});

const vo2maxRecords = (msg.vo2max_response && msg.vo2max_response.data) || [];
vo2maxRecords.forEach(r => {
    if (r.vo2_max === null || r.vo2_max === undefined) return;
    lines.push('oura_vo2_max,day=' + esc(r.day) + ' vo2_max=' + r.vo2_max + ' ' + nowNs);
});

msg.influx_lines = lines;

// SELF-HEAL FIX (PLAN.md §1 TODO, Aug 2026): the curated WardStock summary
// subset now gets pushed to GoDaddy for EVERY day actually present in this
// run's fetched range, not just target_date (the original behavior) — a
// catch-up run that pulls several missed days needs to push all of them,
// or the visible GoDaddy Daily Log gap Ward reported (today synced,
// yesterday didn't) would persist even though the InfluxDB archive above
// already covers the full range regardless of target_date. One POST per
// day happens downstream (n_oura_split_summaries onward) since
// api/oura_push.php only ever accepts one date per call — kept that way
// deliberately rather than changing a proven-working endpoint contract
// for what's normally a one-or-zero-gap-day case.
const daysWithSleep = sleepRecords.filter(r => r.type === 'long_sleep' || r.type === 'sleep').map(r => r.day);
const daysWithActivity = activityRecords.map(r => r.day);
const allDays = [...new Set([...daysWithSleep, ...daysWithActivity])];

const summaries = [];
allDays.forEach(day => {
    const longSleep = sleepRecords.filter(r => r.day === day &&
        (r.type === 'long_sleep' || r.type === 'sleep'))
        .sort((a,b) => (b.total_sleep_duration||0) - (a.total_sleep_duration||0))[0];
    const activity = activityRecords.find(r => r.day === day);

    const summary = { date: day };
    if (longSleep) {
        if (longSleep.total_sleep_duration) summary.sleep_duration_hrs = Math.round((longSleep.total_sleep_duration / 3600) * 100) / 100;
        if (longSleep.efficiency) summary.sleep_efficiency = longSleep.efficiency;
        if (longSleep.lowest_heart_rate) summary.resting_hr = longSleep.lowest_heart_rate;
        if (longSleep.average_hrv) summary.hrv = longSleep.average_hrv;
    }
    if (activity && activity.steps) summary.steps = activity.steps;
    summaries.push(summary);
});
// Guarantee at least one summary always flows through the split/join
// below, even on a genuinely empty response (no data at all in range) —
// matches the original always-one-summary behavior, so job completion
// logging/HA status updates (n_oura_job_success) still fire every run.
if (summaries.length === 0) summaries.push({ date: msg.target_date });
msg.godaddy_summaries = summaries;

return msg;

// Batches all lines from this run into one write request — InfluxDB's
// line protocol accepts multiple points newline-separated in one POST.
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_lines.join('\n');
return msg;

// Manual fan-out, not Node-RED's core `split` node -- real bug,
// Aug 2026: the generic split node failed to correctly isolate each
// array element when targeting a custom-named message property
// (confirmed via wherewhen_data_export_flow.json's own diagnostic
// node.warn output on Ward's real instance -- every downstream
// message was receiving the same unrelated raw text instead of its
// own array element). The one split node in this project using the
// DEFAULT "payload" property (analysis_engine_flow.json's
// n_ae_split) is confirmed working via real usage, which is what
// narrowed this down to custom-property targeting specifically,
// not split() in general. msg.parts is built by hand to match
// exactly what Node-RED's own split node documents, so the paired
// join node (mode: "auto") downstream needs no changes.
const items = msg.godaddy_summaries || [];
const batchId = 'batch_' + Date.now() + '_' + Math.random().toString(36).slice(2);
// Wrapped in an EXTRA array layer -- real bug caught, Aug 2026: a
// function node with a SINGLE output that returns a flat array of
// messages has that array interpreted as "one message per output
// port," so with only 1 output Node-RED took just the first message
// and silently dropped the rest (confirmed: exactly one file -- the
// first measurement -- was ever written, no error). [[...]] is the
// documented way to send many messages down ONE output: the outer
// array is per-output-port, the inner array is the messages for that
// port.
return [items.map((item, i) => {
    const m = Object.assign({}, msg, { payload: item });
    m.parts = { id: batchId, type: 'array', index: i, count: items.length };
    return m;
})];

// msg.payload is one summary object from the n_oura_split_summaries split
// (self-heal fix, PLAN.md §1 TODO) — no longer msg.godaddy_summary.
msg.url = msg.secrets.godaddy_base_url + '/api/oura_push.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify(msg.payload);
return msg;

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=oura_sync,status=success duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = {
    job_name: 'oura_sync', mode: 'success',
    last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: 1,
    // Self-heal checkpoint (PLAN.md §1 TODO) — moved here from its own HA
    // helper (input_datetime.lucius_oura_last_data_date). Advances to today
    // on every successful run, same semantics as before.
    checkpoint: msg.target_date,
};
return msg;

const nowNs = Date.now() * 1000000;
const code = msg.failure_code || 'unknown_error';
const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
msg.influx_finish_point = 'sync_job_runs,job_name=oura_sync,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'oura_sync', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: code + ': ' + (msg.failure_detail || '') };
node.warn('Oura sync failed: ' + code + ' - ' + msg.failure_detail);
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

// Ensures the shared status table exists before every write — cheap
// no-op if it already does. Same idempotent CREATE TABLE IF NOT EXISTS
// discipline as godaddy/sql/upgrade_from_3.0.0.sql, just run inline
// rather than as a separate manual step (Ward, Aug 2026 — "a node red
// task that initializes it, and keeps it up to date"). Identical in
// every flow that writes status — duplicated on purpose, matching this
// project's existing preference for self-contained nodes over a shared-
// context module pattern.
msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

// Builds the UPSERT from msg.sqlite_job (set by job_success/job_failed
// above). 'success' mode updates last_success and clears last_error;
// 'failure' mode updates last_error and deliberately leaves last_success
// untouched (a failure shouldn't erase the last known-good run). checkpoint
// is job-specific optional state (only oura_sync uses it, for its self-heal
// fetch window) — only touched when the caller actually supplies one.
function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
    if (j.checkpoint !== undefined && j.checkpoint !== null) setClauses.push('checkpoint=excluded.checkpoint');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

const rows = msg.payload;
msg.oura_last_data_date = (Array.isArray(rows) && rows[0] && rows[0].checkpoint) ? rows[0].checkpoint : null;
return msg;
